import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'aQjR3wSqj9aObPqMJp10',titulo:'Óculos Inteligente Ai Bv200 Chatgpt Câmera 8mp Bluetooth',listing:'MLB5242031295'},{id:'AUot5FOcnAXK9wLKfANM',titulo:'Vaporizador Portátil de Roupas e Tecidos WAP WAPORE FAST 1250 com Vapor Quente',listing:'MLB5598860072'}];
test('triagem63 protege identidade operação e idempotência; categoria é apenas editorial pública',()=>{for(const r of rows){const p={...r,preco:'salvo',historico:'preservado',linkAfiliado:'https://meli.la/preservar',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p))assert.deepEqual(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{id:'outro'},{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');}});
test('BV200 não é câmera de segurança ou garantia de acesso a serviço de IA',()=>{const x=correctProductData(rows[0]);assert.equal(x.categoria,'informatica');assert.match(x.comentario,/não como uma câmera de segurança/);assert.match(x.comentario,/não é confirmação nossa de conta, assinatura/);assert.doesNotMatch(x.pros,/4K|1200P|horas|UV|grátis|gratuito|ilimitado/i);});
test('WAP exige tensão da unidade e não converte ausência de restrição em liberação de qualquer tecido',()=>{const x=correctProductData(rows[1]);assert.equal(x.categoria,'casa');assert.match(x.comentario,/não presuma bivolt/);assert.match(x.comentario,/isso não significa que qualquer tecido possa receber vapor/);assert.match(x.comentario,/não substitui o ferro/);assert.doesNotMatch(x.pros,/bivolt|bactérias|esteriliz|jeans|universal|alta performance/i);});
test('Eudora mantém texto cauteloso e composição pendente sem importar combo ou refil',()=>{const p={id:'aqN9d0IKYi8X1yUcyFy9',titulo:'Eudora Kit Siàge Liso Intenso (4 Itens)',comentario:'Composição e volumes a confirmar',comparison:null},x=correctProductData(p);for(const k of Object.keys(p))assert.deepEqual(x[k],p[k]);});
test('fichas BV200 e WAP exibem categoria e breadcrumb correspondentes ao catálogo',async()=>{for(const [id,category,label] of [['aQjR3wSqj9aObPqMJp10','informatica','Informática'],['AUot5FOcnAXK9wLKfANM','casa','Casa']]){const html=await readFile(new URL('../produto/'+id+'-20260810-1.html',import.meta.url),'utf8');assert.ok(html.includes('<span>Categoria</span>'+label+'</div>'));assert.ok(html.includes('href="https://rankingdacompra.com.br/analises.html#'+category+'">'+label+'</a>'));for(const m of html.matchAll(/<script\b[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)){const data=JSON.parse(m[1]);for(const node of data['@graph']||[data])if(node['@type']==='BreadcrumbList'){const item=node.itemListElement.find(x=>x.position===2);assert.equal(item.name,label);assert.equal(item.item,'https://rankingdacompra.com.br/analises.html#'+category);}}}});
